   1 +import 'server-only';
   2 +
   3 +import {
   4 +  ENTERPRISE_DENIAL_CODES,
   5 +  type EnterpriseDenial,
   6 +  type EnterpriseDenialCode,
   7 +} from '@agiworkforce/types';
   8 +import { AppError, ErrorCode } from '@/lib/errors';
   9 +
  10 +const DENIAL_STATUS: Readonly<Record<EnterpriseDenialCode, number>> = Object.freeze({
  11 +  not_a_member: 403,
  12 +  plan_does_not_include: 403,
  13 +  permission_denied: 403,
  14 +  primary_owner_only: 403,
  15 +  policy_denied: 403,
  16 +  feature_disabled: 403,
  17 +  surface_not_allowed: 403,
  18 +  region_not_allowed: 403,
  19 +  reasoning_effort_capped: 403,
  20 +  rollout_withheld: 403,
  21 +  self_escalation_denied: 403,
  22 +  policy_unavailable: 503,
  23 +});
  24 +
  25 +export class EnterpriseDenialError extends AppError {
  26 +  constructor(public readonly denial: EnterpriseDenial) {
  27 +    super(
  28 +      denial.code === 'policy_unavailable' ? ErrorCode.SERVICE_UNAVAILABLE : ErrorCode.FORBIDDEN,
  29 +      denial.message,
  30 +      DENIAL_STATUS[denial.code],
  31 +      {
  32 +        code: denial.code,
  33 +        stage: denial.stage,
  34 +        organizationId: denial.organizationId,
  35 +        policyRevision: denial.policyRevision,
  36 +        ...(denial.requiredPermission ? { requiredPermission: denial.requiredPermission } : {}),
  37 +        ...(denial.feature ? { feature: denial.feature } : {}),
  38 +        ...(denial.surface ? { surface: denial.surface } : {}),
  39 +        ...(denial.blockingRule ? { blockingRule: denial.blockingRule } : {}),
  40 +      },
  41 +    );
  42 +    this.name = 'EnterpriseDenialError';
  43 +    Object.setPrototypeOf(this, EnterpriseDenialError.prototype);
  44 +    this.asUserSafe();
  45 +  }
  46 +}
  47 +
  48 +export function isEnterpriseDenialError(error: unknown): error is EnterpriseDenialError {
  49 +  return error instanceof EnterpriseDenialError;
  50 +}
  51 +
  52 +export function isEnterpriseDenialCode(value: unknown): value is EnterpriseDenialCode {
  53 +  return (
  54 +    typeof value === 'string' && (ENTERPRISE_DENIAL_CODES as readonly string[]).includes(value)
  55 +  );
  56 +}

