  23 +
  24 +const MISSING_RELATION = '42P01';
  25 +
  26 +// The layering tables ship as forward migrations that may not be applied. A
  27 +// workspace without them is ungoverned, not unreadable.
  28 +function isMissingRelation(error: unknown): boolean {
  29 +  const code = (error as { code?: unknown } | null)?.code;
  30 +  return code === MISSING_RELATION;
  31 +}
  32 +
  33 +export interface PolicyScopeSelectors {
  34 +  projectId?: string | null;
  35 +  deviceId?: string | null;
  36 +}
  37 +
  38 +interface PolicyOverrideRow {
  39 +  id: string;
  40 +  organization_id: string;
  41 +  subject_type: WorkspacePolicyOverrideSubject;
  42 +  subject_id: string;
  43 +  layer: unknown;
  44 +  updated_at: unknown;
  45 +}
  46 +
  47 +function toIso(value: unknown): string {
  48 +  if (value instanceof Date) return value.toISOString();
  49 +  if (typeof value === 'string') return value;
  50 +  return new Date(0).toISOString();
  51 +}
  52 +
  53 +function formatOverride(row: PolicyOverrideRow): WorkspacePolicyOverride {
  54 +  return {
  55 +    id: row.id,
  56 +    organizationId: row.organization_id,
  57 +    subjectType: row.subject_type,
  58 +    subjectId: row.subject_id,
  59 +    layer: parseWorkspaceControlsLayer(row.layer),
  60 +    updatedAt: toIso(row.updated_at),
  61 +  };
  62 +}
  63 +
  64 +async function readProjectAndDeviceOverrides(
  65 +  db: DatabaseAdapter,
  66 +  organizationId: string,
  67 +  selectors: PolicyScopeSelectors,
  68 +): Promise<WorkspacePolicyOverride[]> {
  69 +  const projectId = selectors.projectId ?? null;
  70 +  const deviceId = selectors.deviceId ?? null;
  71 +  if (!projectId && !deviceId) return [];
  72 +  const rows = await db.query<PolicyOverrideRow>(
  73 +    `select o.id, o.organization_id, o.subject_type, o.subject_id, o.layer, o.updated_at
  74 +       from public.organization_policy_overrides o
  75 +      where o.organization_id = $1
  76 +        and (
  77 +          (o.subject_type = 'project' and $2::text is not null and o.subject_id = $2)
  78 +          or (o.subject_type = 'device' and $3::text is not null and o.subject_id = $3)
  79 +        )`,
  80 +    [organizationId, projectId, deviceId],
  81 +  );
  82 +  return rows.map(formatOverride);
  83 +}
  84 +
  85 +// Project and device are resolved here rather than in
  86 +// readApplicablePolicyOverrides because they depend on the request.
  87 +export async function readScopedPolicyOverrides(
  88 +  db: DatabaseAdapter,
  89 +  organizationId: string,
  90 +  userId: string,
  91 +  selectors: PolicyScopeSelectors = {},
  92 +): Promise<WorkspacePolicyOverride[]> {
  93 +  try {
  94 +    const [subjectOverrides, contextOverrides] = await Promise.all([
  95 +      readApplicablePolicyOverrides(db, organizationId, userId),
  96 +      readProjectAndDeviceOverrides(db, organizationId, selectors),
  97 +    ]);
  98 +    return [...subjectOverrides, ...contextOverrides];
  99 +  } catch (error) {
 100 +    if (!isMissingRelation(error)) throw error;
 101 +    logger.warn(
 102 +      { organizationId },
 103 +      '[authorization] policy layer tables are not present; workspace treated as unlayered',
 104 +    );
 105 +    return [];
 106 +  }
 107 +}
