   1 +import 'server-only';
   2 +
   3 +import type { DatabaseAdapter } from '@agiworkforce/data-layer';
   4 +import {
   5 +  detectPermissionEscalation,
   6 +  ENTERPRISE_DENIAL_STAGE,
   7 +  type OrganizationPermission,
   8 +  type SelfEscalationAttempt,
   9 +} from '@agiworkforce/types';
  10 +import { logger } from '@/lib/logger';
  11 +import { logSecurityEvent, logAuthorizationFailure } from '@/lib/security-audit';
  12 +import { sendSupportEmail } from '@/lib/support/handoff/resend-client';
  13 +import { getHandoffConfig } from '@/lib/support/handoff/config';
  14 +import { EnterpriseDenialError } from '@/lib/authorization/denial';
  15 +
  16 +export interface EscalationCheck {
  17 +  db: DatabaseAdapter;
  18 +  organizationId: string;
  19 +  granterUserId: string;
  20 +  subjectUserId: string;
  21 +  granterPermissions: Iterable<OrganizationPermission>;
  22 +  requestedPermissions: Iterable<OrganizationPermission>;
  23 +  request?: Request;
  24 +}
  25 +
  26 +async function readAlertRecipient(
  27 +  db: DatabaseAdapter,
  28 +  organizationId: string,
  29 +  excludeUserId: string,
  30 +): Promise<string | null> {
  31 +  const [row] = await db.query<{ email: string | null }>(
  32 +    `select p.email
  33 +       from public.organization_members m
  34 +       join public.profiles p on p.id = m.user_id
  35 +      where m.organization_id = $1
  36 +        and m.role = 'owner'
  37 +        and m.user_id <> $2
  38 +        and p.email is not null
  39 +      limit 1`,
  40 +    [organizationId, excludeUserId],
  41 +  );
  42 +  return row?.email ?? null;
  43 +}
  44 +
  45 +// Delivery is best-effort and never decides the request: the grant is already
  46 +// refused by the time this runs, so an unreachable mailbox must not 500.
  47 +async function alertOnSelfEscalation(
  48 +  db: DatabaseAdapter,
  49 +  organizationId: string,
  50 +  attempt: SelfEscalationAttempt,
  51 +): Promise<void> {
  52 +  try {
  53 +    const config = getHandoffConfig();
  54 +    const recipient =
  55 +      (await readAlertRecipient(db, organizationId, attempt.granterUserId)) ?? config.fallbackEmail;
  56 +    const lines = [
  57 +      'A workspace member tried to grant themselves permissions they do not hold.',
  58 +      '',
  59 +      `Workspace: ${organizationId}`,
  60 +      `Member: ${attempt.granterUserId}`,
  61 +      `Permissions refused: ${attempt.escalatedPermissions.join(', ')}`,
  62 +      '',
  63 +      'The grant was refused. Review this member in Settings › Workspace › Roles.',
  64 +    ];
  65 +    const text = lines.join('\n');
  66 +    const result = await sendSupportEmail({
  67 +      to: recipient,
  68 +      subject: 'Security alert: privilege escalation attempt refused',
  69 +      text,
  70 +      html: `<pre>${text.replace(/[&<>]/g, (c) => `&#${c.charCodeAt(0)};`)}</pre>`,
  71 +      idempotencyKey: `escalation:${organizationId}:${attempt.granterUserId}:${attempt.escalatedPermissions.join('|')}`,
  72 +    });
  73 +    if (!result.delivered) {
  74 +      logger.error(
  75 +        { organizationId, reason: result.reason },
  76 +        '[authorization] self-escalation alert was not delivered',
  77 +      );
  78 +    }
  79 +  } catch (error) {
  80 +    logger.error({ error, organizationId }, '[authorization] self-escalation alert failed');
  81 +  }
  82 +}
  83 +
  84 +// The WITH CHECK of both grant tables enforces the same rule. This runs first
  85 +// so the refusal carries a message, an audit record and an alert.
  86 +export async function assertNoPermissionEscalation(
  87 +  check: EscalationCheck,
  88 +): Promise<SelfEscalationAttempt | null> {
  89 +  const attempt = detectPermissionEscalation({
  90 +    granterUserId: check.granterUserId,
  91 +    subjectUserId: check.subjectUserId,
  92 +    granterPermissions: check.granterPermissions,
  93 +    requestedPermissions: check.requestedPermissions,
  94 +  });
  95 +  if (!attempt) return null;
  96 +
  97 +  await logSecurityEvent({
  98 +    userId: attempt.granterUserId,
  99 +    eventType: 'suspicious_activity',
 100 +    severity: 'critical',
 101 +    ...(check.request ? { endpoint: new URL(check.request.url).pathname } : {}),
 102 +    details: {
 103 +      description: attempt.isSelfGrant
 104 +        ? 'privilege escalation: member attempted to grant themselves permissions they do not hold'
 105 +        : 'privilege escalation: member attempted to grant permissions they do not hold',
 106 +      organizationId: check.organizationId,
 107 +      subjectUserId: attempt.subjectUserId,
 108 +      escalatedPermissions: [...attempt.escalatedPermissions],
 109 +    },
 110 +  });
 111 +
 112 +  if (check.request) {
 113 +    await logAuthorizationFailure(
 114 +      check.request,
 115 +      'organization_role_grant',
 116 +      'grant',
 117 +      attempt.granterUserId,
 118 +    );
 119 +  }
 120 +
 121 +  if (attempt.isSelfGrant) {
 122 +    await alertOnSelfEscalation(check.db, check.organizationId, attempt);
 123 +  }
 124 +
 125 +  throw new EnterpriseDenialError({
 126 +    code: 'self_escalation_denied',
 127 +    stage: ENTERPRISE_DENIAL_STAGE.self_escalation_denied,
 128 +    message: 'You cannot grant permissions you do not hold yourself.',
 129 +    organizationId: check.organizationId,
 130 +    policyRevision: 0,
 131 +    blockingRule: attempt.escalatedPermissions.join(','),
 132 +  });
 133 +}

