  13 +
  14 +  const hours = Number(configured);
  15 +  if (!Number.isFinite(hours) || hours <= 0) {
  16 +    return DEFAULT_ABSOLUTE_LIFETIME_HOURS * HOUR_MS;
  17 +  }
  18 +  return hours * HOUR_MS;
  19 +}
  20 +
  21 +export function sessionAbsoluteDeadline(createdAt: number | null): number | null {
  22 +  return createdAt === null ? null : createdAt + sessionAbsoluteLifetimeMs();
  23 +}
