   1 +export const BOT_PROTECTION_ENV_VAR = 'AGI_BOT_PROTECTION';
   2 +export const BOT_PROTECTION_PUBLIC_ENV_VAR = 'NEXT_PUBLIC_AGI_BOT_PROTECTION';
   3 +
   4 +export const BOT_PROTECTION_MODES = {
   5 +  platform: 'platform',
   6 +  off: 'off',
   7 +} as const;
   8 +
   9 +export type BotProtectionMode = (typeof BOT_PROTECTION_MODES)[keyof typeof BOT_PROTECTION_MODES];
  10 +
  11 +const MODE_VALUES: readonly string[] = Object.values(BOT_PROTECTION_MODES);
  12 +
  13 +export function parseBotProtectionMode(raw: string | undefined): BotProtectionMode | undefined {
  14 +  const value = raw?.trim().toLowerCase();
  15 +  if (!value || !MODE_VALUES.includes(value)) return undefined;
  16 +  return value as BotProtectionMode;
  17 +}
  18 +
  19 +export function resolveBotProtectionMode(
  20 +  env: Record<string, string | undefined>,
  21 +  platformHosted: boolean,
  22 +): BotProtectionMode {
  23 +  const configured =
  24 +    parseBotProtectionMode(env[BOT_PROTECTION_ENV_VAR]) ??
  25 +    parseBotProtectionMode(env[BOT_PROTECTION_PUBLIC_ENV_VAR]);
  26 +  if (configured) return configured;
  27 +  return platformHosted ? BOT_PROTECTION_MODES.platform : BOT_PROTECTION_MODES.off;
  28 +}
  29 +
  30 +export function clientBotProtectionMode(): BotProtectionMode {
  31 +  return (
  32 +    parseBotProtectionMode(process.env['NEXT_PUBLIC_AGI_BOT_PROTECTION']) ??
  33 +    BOT_PROTECTION_MODES.platform
  34 +  );
  35 +}

